<?php require_once __DIR__.'/../includes/functions.php';admin_required();$items=[];try{$items=db()->query('SELECT c.*,COUNT(o.id) AS order_count,MAX(o.created_at) AS last_order FROM customers c LEFT JOIN orders o ON o.customer_id=c.id GROUP BY c.id ORDER BY c.created_at DESC')->fetchAll();}catch(Throwable){}$page_title='Customers';require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><header class="admin-header"><span class="eyebrow">CUSTOMERS</span><h1>Data customer</h1></header><section class="table-wrap"><table><thead><tr><th>Nama</th><th>WhatsApp</th><th>Email</th><th>Order</th><th>Terakhir</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['name'])?></td><td><?=e($item['whatsapp'])?></td><td><?=e($item['email']??'-')?></td><td><?=e((string)$item['order_count'])?></td><td><?=e($item['last_order']??'-')?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5">Belum ada customer.</td></tr><?php endif;?></tbody></table></section><?php require __DIR__.'/includes/footer.php';?>
